214	/// Parses a reference: `@target`, `@target[..]`.
215	fn reference(p: &mut Parser) {
216	    let m = p.marker();
217	    p.assert(SyntaxKind::RefMarker);
218	    if p.directly_at(SyntaxKind::LeftBracket) {
219	        content_block(p);
220	    }
221	    p.wrap(m, SyntaxKind::Ref);
222	}
